var MYT = 8 * 36e5;
var DAY = 864e5;
var now = () => Date.now();
var mytDay = (t = now()) => new Date(t + MYT).toISOString().slice(0, 10);
var mytHour = (t = now()) => new Date(t + MYT).getUTCHours();
var daysAgo = (n) => mytDay(now() - n * DAY);
var J = (d, s = 200, h = {}) => new Response(JSON.stringify(d), { status: s, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store", ...h } });
var bad = (m, s = 400) => J({ ok: false, error: m }, s);
var clip = (s, n) => String(s == null ? "" : s).slice(0, n);
var rnd = (n = 16) => [...crypto.getRandomValues(new Uint8Array(n))].map((b) => b.toString(16).padStart(2, "0")).join("");
var parseJ = (s, d) => {
  try {
    const v = JSON.parse(s);
    return v == null ? d : v;
  } catch (e) {
    return d;
  }
};
var rm = (sen) => "RM" + (sen % 100 ? (sen / 100).toFixed(2) : String(sen / 100));
var cleanPhone = (p) => {
  let d = String(p || "").replace(/\D/g, "");
  if (d.startsWith("0")) d = "6" + d;
  if (d && !d.startsWith("60") && d.length <= 10) d = "60" + d;
  return d.length >= 10 && d.length <= 13 ? d : "";
};
