async function publishDue(env, s) {
  if (!s.ig_user_id && s.fb_page_token && now() - +(s.ig_checked || 0) > 6 * 36e5) {
    const ig = await igResolve(env, s).catch(() => null);
    if (ig) {
      s.ig_user_id = ig.id;
      s.ig_username = ig.username;
    }
  }
  env = withSocial(env, s);
  const site = siteUrl(env, s);
  const { results } = await env.DB.prepare("SELECT * FROM posts WHERE status IN ('scheduled','processing') AND scheduled_at<=? ORDER BY scheduled_at LIMIT 4").bind(now()).all();
  let n = 0;
  for (const p of results) {
    if (!AUTO_PLATFORMS.includes(p.platform) || !canAuto(env, p.platform) || s.auto_post !== "1") {
      await env.DB.prepare("UPDATE posts SET status='manual' WHERE id=?").bind(p.id).run();
      continue;
    }
    if (p.status === "processing" && now() - p.scheduled_at < 6e4) continue;
    try {
      const sp = (p.platform === "threads" || p.platform === "facebook" && s.fb_comment_ok !== "0") && s.link_in_reply !== "0" ? splitLink(p.body) : { main: p.body, reply: "" };
      const text = p.platform === "instagram" ? String(p.body || "").replace(/\{LINK\}/g, "\u{1F449} pautan di bio") : postText({ ...p, body: sp.main }, site);
      const res = p.platform === "threads" ? await postThreads(env, p, text) : p.platform === "facebook" ? await postFacebook(env, p, text) : p.platform === "instagram" ? await postInstagram(env, p, text) : await postTelegram(env, p, text);
      if (res.done) {
        let note = null;
        if (sp.reply) {
          try {
            await postReply(env, p.platform, res.id, postText({ ...p, body: sp.reply }, site));
            if (p.platform === "facebook" && s.fb_comment_ok !== "1") await setSetting(env, "fb_comment_ok", "1");
          } catch (e) {
            note = clip(e.message || e, 300);
            if (p.platform === "facebook") await setSetting(env, "fb_comment_ok", "0");
          }
        }
        await env.DB.prepare("UPDATE posts SET status='posted', posted_at=?, ext_id=?, error=? WHERE id=?").bind(now(), res.id, note, p.id).run();
        n++;
      } else await env.DB.prepare("UPDATE posts SET status='processing', ext_id=? WHERE id=?").bind(res.id, p.id).run();
    } catch (e) {
      await env.DB.prepare("UPDATE posts SET status='failed', error=? WHERE id=?").bind(clip(e.message || e, 400), p.id).run();
    }
  }
  if (n) await bump(env, [["posted", n]]);
}
